bool hasCloseElements(List<double> numbers, double threshold) {
  for (int idx = 0; idx < numbers.length; idx++) {
    double elem = numbers[idx];
    for (int idx2 = 0; idx2 < numbers.length; idx2++) {
      double elem2 = numbers[idx2];
      if (idx != idx2) {
        double distance = (elem - elem2).abs();
        if (distance < threshold) {
          return true;
        }
      }
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  // Test case 1
  assert(hasCloseElements([1.0, 2.0, 3.0], 0.5) == false);

  // Test case 2
  assert(hasCloseElements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3) == true);

  print('All tests passed!');
}

